<?php
namespace qqworld_collector\module\cloud_storage; use qqworld_collector\module\cloudStorage1; class upyun extends cloudStorage1 { var $client = null; public function init() { $this->custom_upload_dir = $this->options->cloud_storage_upyun_custom_upload_dir; $this->protocol = $this->options->cloud_storage_upyun_protocol; $this->host = $this->options->cloud_storage_upyun_host; $this->folder = $this->options->cloud_storage_upyun_folder; $this->username = trim($this->options->cloud_storage_upyun_username); $this->password = trim($this->options->cloud_storage_upyun_password); $this->bucket = trim($this->options->cloud_storage_upyun_bucket); $this->cloud_thumbnail = $this->options->cloud_storage_joinmode_enabled ? 0 : filter_var($this->options->cloud_storage_upyun_cloud_thumbnail_enabled, FILTER_VALIDATE_BOOLEAN); $this->cloud_thumbnail_enabled = $this->options->cloud_storage_upyun_cloud_thumbnail_enabled; $this->cloud_thumbnail_structure = $this->options->cloud_storage_upyun_cloud_thumbnail_structure; $this->silent_scanning = $this->options->cloud_storage_upyun_silent_scanning; $this->auto_replace = $this->options->cloud_storage_upyun_auto_replace; $this->sync_delete = $this->options->cloud_storage_upyun_sync_delete; $this->delete_attachment_after_synced = $this->options->cloud_storage_joinmode_enabled ? 0 : $this->options->cloud_storage_upyun_delete_attachment_after_synced; $this->sync_the_website_resource = $this->options->cloud_storage_upyun_sync_the_website_resource; $this->website_resource_filetypes = $this->options->cloud_storage_upyun_website_resource_filetypes; $this->custom_replacement = $this->options->cloud_storage_upyun_custom_replacement; } public function includes() { if ( !class_exists('Upyun') ) require WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'libs' . DIRECTORY_SEPARATOR . 'upyun' . DIRECTORY_SEPARATOR . 'autoload.php'; } public function get_usage() { if ($this->client) { try { $res = $this->client->usage(); $res = json_decode($res, true); if (isset($res['msg'])) { print '<div class="error"><p>' . $res['msg'] . '</p></div>'; } } catch (\Exception $e) { $this->accessed = false; $this->client = null; print '<div class="error"><p>' . $e->getMessage() . '</p></div>'; } } } public function access_service() { if ($this->enabled && $this->is_current && !$this->accessed) { if (!$this->client) { $this->includes(); $this->config = new \Upyun\Config($this->bucket, $this->username, $this->password); $this->client = new \Upyun\Upyun($this->config); $this->accessed = true; } } } public function is_object_exist($destination_path) { $destination_path = preg_replace('/^\/*/i', '', $destination_path); $this->access_service(); try { if (!preg_match('/^\//i', $destination_path, $match)) $destination_path = '/' . $destination_path; $rsp = $this->client->has($destination_path); return $rsp; } catch(Exception $e) { do_action( 'qqworld-collector-log', $this->log_id, 'UPYUN:', $e->getMessage() ); return false; } } public function upload($destination_path, $source_path) { $this->access_service(); if (!file_exists($source_path) || !filesize($source_path)) return false; set_time_limit($this->options->qc_stress_timeout); try { if (!preg_match('/^\//i', $destination_path, $match)) $destination_path = '/' . $destination_path; $content = file_get_contents($source_path); if ($this->is_object_exist($destination_path)) { if ($this->options->cloud_storage_override) { $this->delete_object($destination_path); } else { return true; } } $rsp = $this->client->write($destination_path, $content); return $rsp ? true : false; } catch(Exception $e) { do_action( 'qqworld-collector-log', $this->log_id, 'UPYUN:', $e->getMessage() ); return false; } } public function delete_object($object) { $object = preg_replace('/^\/*/i', '', $object); $this->access_service(); try { if (!preg_match('/^\//i', $object, $match)) $object = '/' . $object; if ($this->is_object_exist($object)) { $rsp = $this->client->delete($object); } return true; } catch(Exception $e) { do_action( 'qqworld-collector-log', $this->log_id, 'UPYUN:', $e->getMessage() ); return false; } } public function add_could_storage_form($guid) { if (file_exists(WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'libs' . DIRECTORY_SEPARATOR . 'upyun' . DIRECTORY_SEPARATOR . 'autoload.php')) { $this->access_service(); $this->get_usage(); require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'cloudStorage-'.$this->guid.'.php'; } else { require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'cloudStorage-'.$this->guid.'-no-sdk.php'; } } public function external_sdk($sdks) { $sdks['cloud-storage']['items']['upyun'] = array( 'label' => __('UpYun Storage Service', $this->text_domain), 'path' => WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'libs' . DIRECTORY_SEPARATOR . 'upyun' . DIRECTORY_SEPARATOR . 'autoload.php', 'download' => 'upyun.zip', 'extract' => true, 'manual' => sprintf(__('Please download <a href="%s" target="_blank"><strong>%s</strong></a> and unzip it to directory <strong>%s</strong>.', $this->text_domain), 'https://pan.qqworld.org/QQWorld%E6%94%B6%E8%97%8F%E5%AE%B6%E8%B1%AA%E5%8D%8E%E7%89%88/%E8%BD%AF%E4%BB%B6%E5%BC%80%E5%8F%91%E5%B7%A5%E5%85%B7%E5%8C%85%EF%BC%88SDK%EF%BC%89', 'upyun.zip', WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'libs' . DIRECTORY_SEPARATOR ) ); return $sdks; } } ?>